p_val, k_val = map(int, input().split())

MAX_LIMITS = int(1e6 + 7)
MOD_VAL = int(1e9 + 7)

cnts = [0] * MAX_LIMITS
visiteds = [0] * MAX_LIMITS
nums = [0] * MAX_LIMITS

def dfs_traverse(x, start):
    count = 1
    while (k_val * x) % p_val != start:
        x = (k_val * x) % p_val
        visiteds[x] = 1
        count += 1
    nums[count] += 1

def isPrimeNumber(x):
    for i in range(2, int(x**0.5) + 1):
        if x % i == 0:
            return False
    return True

divisors_vec = []

if k_val == 0:
    prod = 1
    for _ in range(1, p_val):
        prod = (prod * p_val) % MOD_VAL
    print(prod)
    exit()

for i in range(p_val):
    if not visiteds[i]:
        dfs_traverse(i, i)

for i in range(1, p_val + 1):
    if nums[i]:
        divisors_vec.append(i)

final_product = 1
for i in range(len(divisors_vec)):
    sum_t = 0
    for j in range(len(divisors_vec)):
        if divisors_vec[j] * divisors_vec[j] > divisors_vec[i]:
            break
        if divisors_vec[i] % divisors_vec[j] == 0:
            a = divisors_vec[i] // divisors_vec[j]
            b = divisors_vec[j]
            sum_t += a * nums[a]
            if a != b:
                sum_t += b * nums[b]
            sum_t %= MOD_VAL
    for _ in range(nums[divisors_vec[i]]):
        final_product = (final_product * sum_t) % MOD_VAL

print(final_product)

